"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["3975"],{51911(e,t,o){o.r(t),o.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>i,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"qiangguo/commentsonmaopoems","title":"","description":"Due to Mao Zedong\'s special status, past evaluations of his poetic works have generally lacked objectivity. Those who praise him exalt him to the heavens, while those who bash him drive him into the ground -- all letting their backsides dictate their brains. Here, this young lady shall endeavor to provide an objective evaluation.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/commentsonmaopoems.md","sourceDirName":"qiangguo","slug":"/qiangguo/commentsonmaopoems","permalink":"/en/qiangguo/commentsonmaopoems","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"commentsonmaopoems","title":"","hide_table_of_contents":true,"sidebar_label":"An objective evaluation of Mao Zedong\'s poetry"},"sidebar":"qiangguoSidebar","previous":{"title":"\u6253\u5012\u5B66\u672F\u89C4\u8303\u7684\u6027\u4FDD\u62A4\u4F1E\uFF0C\u6253\u5012\u6BD4\u5993\u5973\u3001\u821E\u7537\u90FD\u4E0D\u5982\u7684\u77E5\u8BC6\u5206\u5B50","permalink":"/en/qiangguo/overthrowintellectuals"},"next":{"title":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 1)","permalink":"/en/qiangguo/maopoemflaws1"}}'),n=o(74848),s=o(28453);let i={id:"commentsonmaopoems",title:"",hide_table_of_contents:!0,sidebar_label:"An objective evaluation of Mao Zedong's poetry"},r="An Objective Evaluation of Mao Zedong's Poetry",l={},h=[];function c(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"an-objective-evaluation-of-mao-zedongs-poetry",children:"An Objective Evaluation of Mao Zedong's Poetry"})}),"\n",(0,n.jsx)(t.p,{children:"Due to Mao Zedong's special status, past evaluations of his poetic works have generally lacked objectivity. Those who praise him exalt him to the heavens, while those who bash him drive him into the ground -- all letting their backsides dictate their brains. Here, this young lady shall endeavor to provide an objective evaluation."}),"\n",(0,n.jsx)(t.p,{children:"Mao Zedong's complete poetic works number fewer than 100 pieces, which by a poet's standards is somewhat sparse in quantity. Traditionally, poets whose works endure through the ages have complete collections of at least 300 poems or more; someone like Lu You had nearly ten thousand. In terms of quality, since some are overly doggerel-like, those that truly meet the basic requirements of classical poetry number fewer than around 50, and those worthy of being passed down through the ages are around 30. In terms of genre, his works are primarily ci lyrics and seven-character regulated verse, which by the standards of a true poet is somewhat narrow. Of course, the significance of Mao Zedong's poetry cannot be measured entirely by ordinary poetic standards, but if we evaluate the poetry purely as poetry, the above analysis is essential."}),"\n",(0,n.jsx)(t.p,{children:"Analyzing at the level of individual words and phrases, his diction and word choice should be classified as average, with occasional strokes of genius, but compared to true masters, there remains a certain distance. Of course, the greatest merit of Mao Zedong's poetry lies in its absence of that musty, antiquated flavor. He made great experimental strides in using classical poetic forms to address modern subjects, though occasionally verging too much on doggerel. Nevertheless, this alone is already quite remarkable. From what we can see today, among those who have achieved this while maintaining a grand manner, Mao Zedong is the best. As for his grandeur, it is related to his life experiences and personality, and this quality is not absent among certain great poets of antiquity, some of whom achieved an even more robust and profound effect."}),"\n",(0,n.jsx)(t.p,{children:"Overall, Mao Zedong's poetry belongs to the category of distinctively styled works, but if viewed purely from the standpoint of poetry alone, it cannot be considered first-rate. However, from the perspective of historical significance, it certainly has lasting value. Moreover, after the May Fourth Movement and the Cultural Revolution, the fact that classical poetry survived at all owes no small debt to Mao Zedong's influence in this regard."})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},28453(e,t,o){o.d(t,{R:()=>i,x:()=>r});var a=o(96540);let n={},s=a.createContext(n);function i(e){let t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:i(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);